 32 │   merge: { booleans: { "--no-squash": "no-squash", "--no-rebase": "no-rebase", "--no-remove": "no-remove", "--no-verify-receipt": "no-verify-receipt", "--ai-message": "ai-message" }, values: { "--message": "message", "-m": "message", "--reason": "reason" }, positional: "[target]" },
 33 │   prune: { booleans: { "--dry-run": "dry-run", "--discard-ignored": "discard-ignored" }, values: { "--min-age": "min-age", "--limit": "limit" }, positional: "" },
 34 │ };
 35 │ 
 36 │ const ALIASES: Record<string, string> = { copy: "copy-ignored", ls: "list", rm: "remove", sw: "switch" };
 37 │ 
 38 │ /** Subcommands that only read. Used by the slash gates and by `runWorktreeCommand`. */
 39 │ const READ_ONLY = new Set(["list", "path"]);
 40 │ /** Subcommands that mutate unless `--dry-run` is given. */
 41 │ const READ_ONLY_WITH_DRY_RUN = new Set(["copy-ignored", "prune"]);
 42 │ 
 43 │ /**
 44 │  * The pre-WP-1310 `/worktree` forms, which act on the speculative worktree of the running session (`nexus run
 45 │  * --worktree`): no argument or `status` shows it, a bare `merge` and `discard` resolve it. `status` is never a
 46 │  * named-worktree subcommand (it is not an alias of `list`), and `merge` with arguments is the named merge, so the CLI
 47 │  * and both slash entry points agree.
 48 │  */
 49 │ const LEGACY = new Set(["", "status", "merge", "discard"]);
 50 │ 
 51 │ export const WORKTREE_USAGE = "worktree [list|path <branch>|switch [-c] <branch> [--base B] [--no-copy]|remove <branch>... [--force] [--delete-unmerged]|copy-ignored [--from B] [--to B] [--force] [--dry-run] [--all-ignored]|merge [target] [--no-squash] [--no-rebase] [--no-remove] [-m message] [--no-verify-receipt --reason why] [--ai-message]|prune [--dry-run] [--min-age 1d] [--limit N] [--discard-ignored]]";
