 53 │ /** The subcommand a token names, matched case-insensitively (the slash gates lowercase their input; the CLI does not). */
 54 │ function canonical(sub: string): string | undefined {
 55 │   const key = sub.toLowerCase();
 56 │   const name = ALIASES[key] ?? key;
 57 │   return SPECS[name] ? name : undefined;
 58 │ }
 59 │ 
 60 │ function firstWord(args: string): string {
 61 │   return (args.trim().split(/\s+/)[0] ?? "").toLowerCase();
 62 │ }
 63 │ 
 64 │ /** True when `args` (the text after `/worktree`) is one of the legacy speculative-worktree forms. */
 65 │ export function isLegacyWorktreeArgs(args: string): boolean {
 66 │   const first = firstWord(args);
 67 │   // A bare `merge` resolves the speculative worktree. `merge <target>` or `merge <flags>` is the named-worktree merge
 68 │   // (`/worktree merge ^` merges into the default branch), so both stay reachable from the slash commands.
 69 │   if (first === "merge") return args.trim().split(/\s+/).length === 1;
 70 │   return LEGACY.has(first);
 71 │ }
 72 │ 
 73 │ /**
 74 │  * True when `args` (the text after `/worktree` or `nexus worktree`) only inspects. Empty args are the legacy speculative
 75 │  * `status` form that the slash entry points run (read-only); only the `nexus worktree` command maps no subcommand to `list`.
 76 │  */
 77 │ export function isReadOnlyWorktreeArgs(args: string): boolean {
 78 │   const sub = firstWord(args);
 79 │   if (isLegacyWorktreeArgs(sub)) return sub === "" || sub === "status";
 80 │   const name = canonical(sub);
 81 │   if (name === undefined) return false;
 82 │   if (READ_ONLY.has(name)) return true;
 83 │   return READ_ONLY_WITH_DRY_RUN.has(name) && args.trim().split(/\s+/).includes("--dry-run");
 84 │ }
