 86 │ function parse(spec: Spec, tokens: string[]): Parsed {
 87 │   const parsed: Parsed = { positionals: [], flags: new Set(), values: new Map() };
 88 │   for (let i = 0; i < tokens.length; i++) {
 89 │     const token = tokens[i];
 90 │     if (token === "--") { parsed.positionals.push(...tokens.slice(i + 1)); break; }
 91 │     if (token.length > 1 && token.startsWith("-")) {
 92 │       if (spec.booleans[token]) parsed.flags.add(spec.booleans[token]);
 93 │       else if (spec.values[token]) {
 94 │         const value = tokens[++i];
 95 │         if (value === undefined) throw new WorktreeError(`${token} needs a value`);
 96 │         parsed.values.set(spec.values[token], value);
 97 │       } else throw new WorktreeError(`unknown option ${redactSecrets(token).slice(0, 40)}`);
 98 │       continue;
 99 │     }
100 │     parsed.positionals.push(token);
101 │   }
102 │   return parsed;
103 │ }
104 │ 
105 │ /** Runs one worktree command. Never throws: failures come back as `success: false` with a redacted message. */
106 │ export function runWorktreeCommand(tokens: string[], run: RunContext): CommandResult {
107 │   const ctx: WorktreeContext = { cwd: run.cwd, home: run.home ?? homeDir(), readOnly: Boolean(run.readOnly) };
108 │   try {
109 │     const first = tokens[0] && !tokens[0].startsWith("-") ? tokens[0] : "list";
110 │     const rest = first === tokens[0] ? tokens.slice(1) : tokens;
111 │     const name = canonical(first);
112 │     if (!name) throw new WorktreeError(`unknown subcommand '${redactSecrets(first).slice(0, 40)}'. Usage: ${WORKTREE_USAGE}`);
113 │     const parsed = parse(SPECS[name], rest);
114 │     if (ctx.readOnly && !READ_ONLY.has(name) && !(READ_ONLY_WITH_DRY_RUN.has(name) && parsed.flags.has("dry-run"))) {
115 │       throw new WorktreeError(`read-only mode: 'worktree ${name}' changes the repository and is refused`);
116 │     }
117 │     switch (name) {
118 │       case "switch": {
119 │         if (parsed.positionals.length !== 1) throw new WorktreeError("usage: worktree switch [-c] <branch> [--base B]");
120 │         const switched = switchWorktree(ctx, parsed.positionals[0], { create: parsed.flags.has("create"), base: parsed.values.get("base") });
121 │         const made = switched.data as { created?: boolean; path?: string } | undefined;
122 │         if (switched.success && made?.created && !parsed.flags.has("no-copy") && made.path) {
123 │           // Sharing build caches is a convenience: a failure here never undoes or fails the switch, but it is said.
124 │           try {
125 │             const copied = copyIgnored(ctx, { to: made.path });
126 │             const data = copied.data as { copied?: number } | undefined;
127 │             if (!copied.success) switched.output += `\nwarning: ignored files were not copied: ${copied.output}`;
128 │             else if (data?.copied) switched.output += `\n${copied.output}`;
129 │           } catch (err) {
130 │             switched.output += `\nwarning: copying ignored files failed: ${redactSecrets((err as Error).message).slice(0, 200)}`;
131 │           }
132 │         }
133 │         return switched;
134 │       }
135 │       case "copy-ignored": {
136 │         if (parsed.positionals.length) throw new WorktreeError("usage: worktree copy-ignored [--from B] [--to B] [--force] [--dry-run] [--all-ignored]");
137 │         return copyIgnored(ctx, {
138 │           from: parsed.values.get("from"), to: parsed.values.get("to"), force: parsed.flags.has("force"),
139 │           dryRun: parsed.flags.has("dry-run"), allIgnored: parsed.flags.has("all-ignored"),
140 │         });
141 │       }
142 │       case "list": {
143 │         if (parsed.positionals.length) throw new WorktreeError("usage: worktree list [--json] [--limit N]");
144 │         const limit = parsed.values.get("limit");
145 │         if (limit !== undefined && !/^[1-9]\d{0,5}$/.test(limit)) throw new WorktreeError("--limit must be a positive integer");
146 │         return listWorktrees(ctx, { json: parsed.flags.has("json"), limit: limit ? Number(limit) : undefined });
147 │       }
148 │       case "path": {
149 │         if (parsed.positionals.length !== 1) throw new WorktreeError("usage: worktree path <branch|path>");
150 │         return pathOf(ctx, parsed.positionals[0]);
151 │       }
152 │       case "merge": {
153 │         if (parsed.positionals.length > 1) throw new WorktreeError("usage: worktree merge [target] [--no-squash] [--no-rebase] [--no-remove] [-m message] [--ai-message] [--no-verify-receipt --reason why]");
154 │         return mergeWorktree(ctx, mergeOptionsFrom(parsed));
155 │       }
156 │       case "prune": {
157 │         if (parsed.positionals.length) throw new WorktreeError("usage: worktree prune [--dry-run] [--min-age 1d] [--limit N] [--discard-ignored]");
158 │         const limit = parsed.values.get("limit");
159 │         if (limit !== undefined && !/^[1-9]\d{0,5}$/.test(limit)) throw new WorktreeError("--limit must be a positive integer");
160 │         const age = parsed.values.get("min-age");
161 │         return pruneWorktrees(ctx, {
162 │           dryRun: parsed.flags.has("dry-run"), discardIgnored: parsed.flags.has("discard-ignored"),
163 │           minAgeMs: age === undefined ? undefined : parseAge(age), limit: limit ? Number(limit) : undefined,
164 │         });
165 │       }
166 │       case "remove":
167 │         return removeWorktrees(ctx, parsed.positionals, { force: parsed.flags.has("force"), deleteUnmerged: parsed.flags.has("delete-unmerged") });
168 │     }
169 │     throw new WorktreeError("unreachable");
170 │   } catch (err) {
171 │     return formatCommandError(err);
172 │   }
173 │ }
174 │ 
175 │ function mergeOptionsFrom(parsed: Parsed): MergeOptions {
176 │   return {
177 │     target: parsed.positionals[0],
178 │     noSquash: parsed.flags.has("no-squash"),
179 │     noRebase: parsed.flags.has("no-rebase"),
180 │     noRemove: parsed.flags.has("no-remove"),
181 │     message: parsed.values.get("message"),
182 │     noVerifyReceipt: parsed.flags.has("no-verify-receipt"),
183 │     reason: parsed.values.get("reason"),
184 │   };
185 │ }
186 │ 
187 │ function formatCommandError(err: unknown): CommandResult {
188 │   if (err instanceof WorktreeError || err instanceof WorktreePathError || err instanceof GitError) {
189 │     return { success: false, output: redactSecrets(err.message) };
190 │   }
191 │   return { success: false, output: redactSecrets((err as Error)?.message ?? String(err)).slice(0, 400) };
192 │ }
193 │ 
194 │ /** Split the text after the command name into tokens, preserving single- and double-quoted strings. */
195 │ export function tokenizeWorktreeArgs(args: string): string[] {
196 │   const tokens: string[] = [];
197 │   const regex = /"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\S+)/g;
198 │   let match: RegExpExecArray | null;
199 │   while ((match = regex.exec(args)) !== null) {
200 │     if (match[1] !== undefined) {
201 │       tokens.push(match[1].replace(/\\(["\\])/g, "$1"));
202 │     } else if (match[2] !== undefined) {
203 │       tokens.push(match[2].replace(/\\(['\\])/g, "$1"));
204 │     } else if (match[3] !== undefined) {
205 │       tokens.push(match[3]);
206 │     }
207 │   }
208 │   return tokens;
209 │ }
210 │ 
211 │ /**
212 │  * Where an interactive session standing in a worktree that a command just removed should move to: the worktree of the
213 │  * branch the work was merged into. Undefined when nothing was removed or the session is elsewhere.
214 │  */
215 │ export function relocationAfter(result: CommandResult, cwd: string): string | undefined {
216 │   const data = result.data as { removedPath?: string; targetPath?: string } | undefined;
217 │   if (!result.success || !data?.removedPath || !data.targetPath) return undefined;
218 │   const removed = data.removedPath;
219 │   const inside = (candidate: string) => candidate === removed || candidate.startsWith(removed + path.sep);
220 │   return inside(cwd) || inside(canonicalAfterRemoval(cwd)) ? data.targetPath : undefined;
221 │ }
222 │ 
223 │ /** `realpath` for a path whose tail may be gone: resolves links (also dangling ones) and the deepest existing ancestor. */
224 │ function canonicalAfterRemoval(file: string, depth = 0): string {
225 │   const absolute = path.resolve(file);
226 │   try {
227 │     return fs.realpathSync(absolute);
228 │   } catch {
229 │     if (depth > 20) return absolute;
230 │     try {
231 │       if (fs.lstatSync(absolute).isSymbolicLink()) return canonicalAfterRemoval(path.resolve(path.dirname(absolute), fs.readlinkSync(absolute)), depth + 1);
232 │     } catch { /* not there at all */ }
233 │     const parent = path.dirname(absolute);
234 │     return parent === absolute ? absolute : path.join(canonicalAfterRemoval(parent, depth + 1), path.basename(absolute));
235 │   }
236 │ }
237 │ 
238 │ export interface AsyncDeps {
239 │   /** Asks the configured model; absent when no provider is available. */
240 │   completer?: Completer;
241 │   aiTimeoutMs?: number;
242 │   /** An operator cancel (Ctrl-C) while the model is being asked: the merge does not start. */
243 │   signal?: AbortSignal;
244 │ }
245 │ 
246 │ /** Like `runWorktreeCommand`, plus the opt-in `merge --ai-message`. Read-only mode never reaches the model. */
247 │ export async function runWorktreeCommandAsync(tokens: string[], run: RunContext, deps: AsyncDeps = {}): Promise<CommandResult> {
248 │   const name = tokens[0] ? canonical(tokens[0]) : undefined;
249 │   if (name !== "merge" || run.readOnly) return runWorktreeCommand(tokens, run);
250 │   let parsed: Parsed;
251 │   try { parsed = parse(SPECS.merge, tokens.slice(1)); } catch { return runWorktreeCommand(tokens, run); }
252 │   if (!parsed.flags.has("ai-message") || parsed.values.has("message")) return runWorktreeCommand(tokens, run); // an explicit message wins
253 │   if (parsed.positionals.length > 1) return runWorktreeCommand(tokens, run); // the one place that owns the merge usage
254 │   const ctx: WorktreeContext = { cwd: run.cwd, home: run.home ?? homeDir(), readOnly: false };
255 │ 
256 │   const mergeOptions = mergeOptionsFrom(parsed);
257 │   let mctx: MergeContextInfo;
258 │   try {
259 │     mctx = resolveMergeContext(ctx, mergeOptions);
260 │   } catch (err) {
261 │     return formatCommandError(err);
262 │   }
263 │ 
264 │   const aiOptions: MergeOptions = { ...mergeOptions, amendSingleCommit: true };
265 │   if (!writesCommitMessage(mctx, aiOptions)) {
266 │     return runWorktreeCommand(tokens, run); // nothing to describe: the ordinary path
267 │   }
268 │ 
269 │   if (deps.signal?.aborted) return { success: false, output: "Cancelled before the model was asked: nothing was merged, committed or removed." };
270 │   const generated = await generateMergeMessage(mctx, deps.completer, deps.aiTimeoutMs ?? DEFAULT_AI_TIMEOUT_MS, deps.signal, mergeOptions);
271 │ 
272 │   if (deps.signal?.aborted) return { success: false, output: "Cancelled while the model was being asked: nothing was merged, committed or removed." };
273 │ 
274 │   try {
275 │     const options: MergeOptions = { ...aiOptions, target: mctx.targetName, expectedState: { branch: mctx.branch, head: mctx.gateState.head, tree: mctx.gateState.tree }, ...(generated.message ? { message: generated.message } : {}) };
276 │     const result = mergeWorktree(ctx, options);
277 │     return { ...result, output: `${generated.note}\n${result.output}` };
278 │   } catch (err) {
279 │     return formatCommandError(err);
280 │   }
281 │ }

