 33 │   git(repo, "commit", "-q", "-m", "init");
 34 │   const made = runWorktreeCommand(["switch", "-c", name, "--no-copy"], { cwd: repo, home, readOnly: false });
 35 │   assert.equal(made.success, true, made.output);
