 40 │ /** Rewrites the worktree's `.git` pointer to a repository planted INSIDE the worktree whose config runs `marker`-writing commands. */
 41 │ function plantRepository(f: ReturnType<typeof fixture>, branch: string, config: string[]): string {
 42 │   const marker = path.join(f.root, "MARKER");
