  const records = out.split("\0");
  for (let i = 0; i < records.length; i++) {
    const record = records[i];
    if (!record) continue;
    const kind = record[0];
    if (kind === "1" || kind === "2") {
      if (record[2] !== ".") dirty.staged++;
